// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.consolidationimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.memory.repository.EpisodicMemoryRepositoryimport com.roshan.persona.memory.repository.KnowledgeGraphRepositoryimport com.roshan.persona.memory.repository.SemanticFactRepositoryimport com.roshan.persona.memory.vector.VectorSearchEngineimport timber.log.Timberimport kotlin.math.exp/** * NOUS — Consolidation Engine (Dream Mode). * * Runs nightly (2-4 AM, charging, idle) to consolidate memories. * 7 phases inspired by human sleep consolidation: * *   Phase 1: Episodic → Semantic promotion (frequently recalled → facts) *   Phase 2: LLM-driven KG enrichment (extract entities + relationships) *   Phase 3: Importance decay + hot cache expiry (Ebbinghaus curve) *   Phase 4: Incremental vector indexing (add new, no full rebuild) *   Phase 5: Consolidation compression (summarize old low-importance) *   Phase 6: Prospective memory check (fire due reminders) *   Phase 7: VACUUM (physically delete tombstoned rows + reclaim space) * * @see <a href="docs/strategy/module-3-strategy-v2.md">§6 Memory Consolidation</a> */class ConsolidationEngine(    private val episodicRepo: EpisodicMemoryRepository,    private val semanticRepo: SemanticFactRepository,    private val kgRepo: KnowledgeGraphRepository,    private val vectorEngine: VectorSearchEngine,) {    /**     * Run full consolidation cycle (all 7 phases).     * Called by WorkManager during idle + charging (2-4 AM).     *     * @return ConsolidationResult with stats from each phase     */    suspend fun runFullConsolidation(): ConsolidationResult {        Timber.i("Dream Mode: Starting full consolidation cycle")        val phase1 = phase1EpisodicToSemantic()        val phase2 = phase2KgEnrichment()        val phase3 = phase3DecayAndExpiry()        val phase4 = phase4VectorIndexing()        val phase5 = phase5Compression()        val phase6 = phase6ProspectiveCheck()        val phase7 = phase7Vacuum()        val result = ConsolidationResult(            promotedToFacts = phase1,            kgEdgesCreated = phase2,            memoriesDecayed = phase3,            vectorsIndexed = phase4,            memoriesCompressed = phase5,            remindersFired = phase6,            rowsVacuumed = phase7,        )        Timber.i("Dream Mode complete: $result")        return result    }    /**     * Phase 1: Episodic → Semantic Promotion.     * Find memories recalled 3+ times in last 7 days → extract as facts.     */    private suspend fun phase1EpisodicToSemantic(): Int {        // Simplified: check recent memories for patterns        // Production would track recall count and use LLM for extraction        return 0    }    /**     * Phase 2: LLM-Driven KG Enrichment.     * Pass batch of episodic memories to LLM for entity/relationship extraction.     * Enforce JSON schema output.     */    private suspend fun phase2KgEnrichment(): Int {        // Simplified: skip LLM extraction (needs Module 4 LLM)        // Production would: pass memories to LLM, parse JSON, create entities + edges        return 0    }    /**     * Phase 3: Importance Decay + Hot Cache Expiry.     * Apply Ebbinghaus decay: importance *= e^(-t/decayConstant).     * Expire hot cache flag for memories older than 24h.     */    private suspend fun phase3DecayAndExpiry(): Int {        // Ebbinghaus: importance(t) = initial * e^(-t / decayConstant)        // decayConstant = 7 days (confirmed Q8)        // Simplified: would call dao.applyDecay(0.99f) and dao.expireHotCache()        return 0    }    /**     * Phase 4: Incremental Vector Indexing.     * Process pending embeddings (status = "pending").     * Add to HNSW incrementally — NO full rebuild.     */    private suspend fun phase4VectorIndexing(): Int {        val pending = vectorEngine.getPendingEmbeddings(32)        for (memoryId in pending) {            vectorEngine.updateEmbeddingStatus(memoryId, "computing")            // Production would: compute embedding via TFLite MiniLM            // For now: skip (needs Module 6 Vision for embedder)            vectorEngine.updateEmbeddingStatus(memoryId, "failed")        }        return 0    }    /**     * Phase 5: Consolidation Compression.     * Take 5 oldest low-importance memories, LLM summarizes into 1 "super-memory".     * Tombstone the original 5.     */    private suspend fun phase5Compression(): Int {        // Simplified: skip (needs Module 4 LLM for summarization)        return 0    }    /**     * Phase 6: Prospective Memory Check.     * Fire notifications for due reminders. Expire past-due non-recurring.     */    private suspend fun phase6ProspectiveCheck(): Int {        // Would check prospective_memories table for due items        return 0    }    /**     * Phase 7: VACUUM.     * Physically DELETE tombstoned rows. Run SQLite VACUUM to reclaim space.     * Rebuild HNSW index if > 20% vectors were tombstoned.     */    private suspend fun phase7Vacuum(): Int {        vectorEngine.vacuum()        return 0    }}/** * Stats from consolidation cycle. */data class ConsolidationResult(    val promotedToFacts: Int,    val kgEdgesCreated: Int,    val memoriesDecayed: Int,    val vectorsIndexed: Int,    val memoriesCompressed: Int,    val remindersFired: Int,    val rowsVacuumed: Int,) {    override fun toString(): String =        "promoted=$promotedToFacts, kgEdges=$kgEdgesCreated, decayed=$memoriesDecayed, " +        "indexed=$vectorsIndexed, compressed=$memoriesCompressed, fired=$remindersFired, vacuumed=$rowsVacuumed"}
